# Packer: the same role that patches live hosts also bakes the image
build {
  sources = ["source.amazon-ebs.base"]

  provisioner "ansible" {
    playbook_file   = "./playbooks/baseline.yml"
    extra_arguments = ["--extra-vars", "build_mode=image"]
  }
}

# Scheduled drift detection on surviving mutable hosts:
# any reported change is something Ansible did not put there.
ansible-playbook baseline.yml --check --diff | tee drift.log
